package com.erudit.quiz;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.erudit.integration.InternalClients.*;import com.erudit.integration.InternalContracts.*;import com.erudit.quiz.model.CompetitionModels.*;import com.erudit.quiz.repository.CompetitionRepository;import com.erudit.quiz.service.CompetitionService;import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.ObjectProvider;
class CompetitionServiceTest {@Test void invitesIdempotentlyAndFallsBackWhenDependencyIsDown(){var repository=mock(CompetitionRepository.class);var users=mock(ObjectProvider.class);var notifications=mock(ObjectProvider.class);var userClient=mock(UserClient.class);var notifier=mock(NotificationClient.class);when(users.getIfAvailable()).thenReturn(userClient);when(notifications.getIfAvailable()).thenReturn(notifier);UUID competition=UUID.randomUUID(),user=UUID.randomUUID(),actor=UUID.randomUUID();when(userClient.get(user)).thenReturn(new UserLookup(user,"User",true));var service=new CompetitionService(repository,users,notifications,CircuitBreakerRegistry.ofDefaults());service.invite(competition,user,actor);verify(repository).invite(competition,user,actor);verify(notifier).enqueue(any(Notification.class));when(userClient.get(user)).thenThrow(new IllegalStateException());assertThatThrownBy(()->service.invite(competition,user,actor)).isInstanceOf(IllegalStateException.class);}}
